from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty or missing values are zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold subject to legacy ACC-004 validation."""
    updated_account = account.copy()

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _numeric_value(account.get("CRED_LIMIT", "")) <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": account.get("ACCT_ID", ""),
        }
    ]
